// A test palette: one shade, from red to blue, set by its control.

class ScenarioPalette {
  byte shade = 100;

  void defineControls() {
    addControl("shade", shade, 0, 255); // where between red and blue
  }

  void tick() {
    for (int i = 0; i < 16; i = i + 1) {
      setPalEntry(i, shade, 0, 255 - shade);
    }
  }
}
